const char* powerStampName(PowerId id) {
    int i = (int)id - 1; // NONE=0; entry 0 == first alphabetical id
    if (i < 0 || i >= (int)(sizeof(kPowerNames) / sizeof(kPowerNames[0]))) return nullptr;
    return kPowerNames[i].stamp;
}

PowerId powerIdFromStampName(const char* name) {
    for (const auto& e : kPowerNames)
        if (std::strcmp(e.stamp, name) == 0) return e.id;
    return PowerId::NONE;
}

